import {connect} from 'react-redux'

import type {DialogOwnProps, DialogProps} from '../../../../hocs/withDialogContainer'
import withDialogContainer from '../../../../hocs/withDialogContainer'
import type {State} from '../../../../reducers/types'
import {getBuild} from '../../../../selectors'
import type {BuildId} from '../../../../types'
import {DialogType} from '../../../../types'

import CommentDialog from './CommentDialog'
import {saveComment} from './CommentDialog.actions'

type BaseProps = {
  buildIds: readonly BuildId[]
}

type OwnProps = DialogOwnProps<BaseProps>
type Props = DialogProps<BaseProps>
type StateProps = {
  comment: string
}

const mapStateToProps = (state: State, {buildIds}: Props): StateProps => ({
  comment: buildIds.length > 1 ? '' : (getBuild(state, buildIds[0])?.comment?.text ?? ''),
})

const actionCreators = {
  saveComment,
}

export default withDialogContainer(DialogType.COMMENT, (_, {buildIds}: OwnProps) =>
  buildIds.join(','),
)(connect(mapStateToProps, actionCreators)(CommentDialog))
