import {skipToken} from '@reduxjs/toolkit/query'

import {useAppSelector} from '../../../hooks/react-redux'
import {getInvestigationArg} from '../../../rest/investigations'
import type {Branch} from '../../../services/rest'
import {restApi} from '../../../services/rest'
import type {BuildTypeId} from '../../../types'
import {InvestigationStates} from '../../../types'

import {getIsBuildTypeFailure} from './Investigations.selectors'

export function useSkipAssignInvestigation(
  buildTypeId: BuildTypeId | null | undefined,
  branch: Branch | null | undefined,
  forceFalse?: boolean,
) {
  const isBuildTypeFailure = useAppSelector(state =>
    getIsBuildTypeFailure(state, buildTypeId, branch),
  )
  const {hasInvestigation} = restApi.endpoints.getAllInvestigations.useQuery(
    !forceFalse && buildTypeId != null ? getInvestigationArg(buildTypeId) : skipToken,
    {
      selectFromResult: ({data}) => {
        const {state} = data?.investigation?.[0] ?? {}
        return {hasInvestigation: state != null && state !== InvestigationStates.NONE}
      },
    },
  )
  return !forceFalse && isBuildTypeFailure === true && !hasInvestigation
}
