import {branch, renderNothing} from 'recompose'

import compose from 'lodash/flowRight'
import type {ResolveThunks} from 'react-redux'
import {connect} from 'react-redux'

import withDialogContainer from '../../../../hocs/withDialogContainer'
import type {DialogProps} from '../../../../hocs/withDialogContainer'
import withSuspense from '../../../../hocs/withSuspense'
import type {State} from '../../../../reducers/types'
import {makeGetTags} from '../../../../selectors'
import type {BuildId, BuildTypeId, HOC, Tag} from '../../../../types'
import {DialogType} from '../../../../types'
import {emptyArray} from '../../../../utils/empty'

import TagDialog from './TagDialog'
import {changeBuildTags} from './TagDialog.actions'

type BaseProps = {
  buildIds: readonly BuildId[]
  buildTypeId?: BuildTypeId
  onAction?: () => unknown
}
type ReduxOwnProps = DialogProps<BaseProps>
type StateProps = {
  tags: ReadonlyArray<Tag>
}
const actionCreators = {
  saveTags: changeBuildTags,
}

const mapStateToProps: () => (arg0: State, arg1: ReduxOwnProps) => StateProps = () => {
  const getTags = makeGetTags()
  return (state, {buildIds}) => {
    const tags = buildIds.length > 1 ? emptyArray : getTags(state, buildIds[0])
    return {
      tags,
    }
  }
}

const connector: HOC<
  ReduxOwnProps & StateProps & ResolveThunks<typeof actionCreators>,
  ReduxOwnProps
> = connect(mapStateToProps, actionCreators)

export default compose(
  withDialogContainer<BaseProps>(DialogType.TAGS, (_, {buildIds}) => buildIds.join(',')),
  branch((props: ReduxOwnProps) => !props.isOpened, renderNothing),
  connector,
  withSuspense(),
)(TagDialog)
