import {getSaveBuildsCommentArg} from '../../../../rest/builds'
import {restApi} from '../../../../services/rest'
import type {BuildId} from '../../../../types'

export type SaveCommentArg = {
  buildIds: readonly BuildId[]
  text: string
}
export const saveComment = ({buildIds, text}: SaveCommentArg) =>
  restApi.endpoints.setMultipleBuildComments.initiate(getSaveBuildsCommentArg(buildIds, text))
