import CommentIcon from '@jetbrains/icons/comment.svg'
import PinEmptyIcon from '@jetbrains/icons/pin-empty.svg'
import PinFilledIcon from '@jetbrains/icons/pin-filled.svg'
import StarEmptyIcon from '@jetbrains/icons/star-empty.svg'
import StarFilledIcon from '@jetbrains/icons/star-filled.svg'
import TagIcon from '@jetbrains/icons/tag.svg'
import type {ListDataItem} from '@jetbrains/ring-ui-built/components/list/consts'
import compose from 'lodash/flowRight'
import type {ComponentType} from 'react'
import * as React from 'react'
import {Suspense, useMemo} from 'react'
import {connect} from 'react-redux'

import {openDialog} from '../../../actions'
import {withBuildId} from '../../../hooks/routes'
import {usePermission} from '../../../hooks/usePermission'
import type {State} from '../../../reducers/types'
import {getBuild, getBuildType, getIsSakuraUI, getIsStarred, getTagsCount} from '../../../selectors'
import type {Branch} from '../../../services/rest'
import type {BuildId, BuildTypeId, ProjectId} from '../../../types'
import {DialogType, Permission, ROOT_PROJECT_ID, stringifyId} from '../../../types'
import {parseBranch} from '../../../utils/branchNames'
import {getOldWebBuildLink} from '../../../utils/entityLinks'
import {notNull} from '../../../utils/guards'
import BuildTypeInvestigationHistoryPopup from '../../packages/InvestigationHistory/BuildTypeInvestigationHistoryPopup/BuildTypeInvestigationHistoryPopup'
import {useCompareDropdownActionItem} from '../../pages/CompareBuildsPage/ChooseCompareBuilds/ChooseCompareBuilds.hooks'
import ActionsDropdown from '../ActionsDropdown/ActionsDropdown.container'
import type {ActionsDropdownOwnProps} from '../ActionsDropdown/ActionsDropdown.types'
import CustomizedBuildSection from '../CustomizedBuildNote/CustomizedBuildNote.lazy'
import {useSkipAssignInvestigation} from '../Investigations/Investigations.hooks'
import {starBuild} from '../StarBuild/StarBuild.actions'

import CommentDialog from './CommentDialog/CommentDialog.container'
import PinDialog, {EditPinCommentDialog} from './PinDialog/PinDialog.container'
import TagDialog from './TagDialog/TagDialog.container'

type ActionDropdownStateProps = {
  entityHref: string | null | undefined
  branch: Branch | null | undefined
  icon?: string
}
export type BuildActionsDropdownProps = Omit<
  ActionsDropdownOwnProps,
  keyof ActionDropdownStateProps
> & {
  fromBuildList?: boolean
  isPinnable?: boolean
  isTaggable?: boolean
  onAction?: () => unknown
  seqKey?: string
}
type ReduxOwnProps = BuildActionsDropdownProps & {
  buildId?: BuildId
}
type ActionProps = {
  onStar: (arg0: BuildId, arg1: boolean) => Promise<unknown>
  openDialogAction: (arg0: string, arg1: DialogType) => unknown
}
type StateProps = ActionDropdownStateProps & {
  projectId: ProjectId | null | undefined
  buildTypeId?: BuildTypeId
  isFinishedBuild: boolean
  comment: string | null | undefined
  isPinned?: boolean
  isStarred: boolean
  tagsCount: number
}
type Props = ReduxOwnProps & StateProps & ActionProps
const actionCreators = {
  onStar: starBuild,
  openDialogAction: openDialog,
}

const beforeList = <CustomizedBuildSection embedded />

function OverviewActionsContainer({
  isPinned,
  isStarred,
  tagsCount,
  comment,
  buildTypeId,
  buildId,
  isPinnable,
  isFinishedBuild,
  isTaggable,
  fromBuildList,
  openDialogAction,
  onStar,
  projectId,
  branch,
  onAction,
  ...restProps
}: Props) {
  const isCommentable = usePermission(Permission.COMMENT_BUILD, projectId)
  const canTagBuild = usePermission(Permission.TAG_BUILD, projectId)
  const isActuallyTaggable = isTaggable !== false && canTagBuild
  const canChangeOwnProfile = usePermission(Permission.CHANGE_OWN_PROFILE, ROOT_PROJECT_ID)
  const isStarrable = canTagBuild && canChangeOwnProfile
  const canPinUnpinBuild = usePermission(Permission.PIN_UNPIN_BUILD, projectId)
  const isActuallyPinnable = isPinnable !== false && isFinishedBuild && canPinUnpinBuild

  const buildIdAsString = stringifyId(buildId)
  const handlePin = React.useCallback(() => {
    openDialogAction(buildIdAsString, DialogType.PIN)
  }, [openDialogAction, buildIdAsString])
  const handleTags = React.useCallback(() => {
    openDialogAction(buildIdAsString, DialogType.TAGS)
  }, [openDialogAction, buildIdAsString])
  const handleComment = React.useCallback(() => {
    openDialogAction(buildIdAsString, DialogType.COMMENT)
  }, [openDialogAction, buildIdAsString])
  const handleStar = React.useCallback(async () => {
    if (buildId != null) {
      await onStar(buildId, !isStarred)
      onAction?.()
    }
  }, [buildId, onStar, isStarred, onAction])
  const compareDropdownActionItem = useCompareDropdownActionItem(buildId)
  const items: ListDataItem[] = useMemo(
    () =>
      [
        isActuallyPinnable
          ? {
              label: isPinned ? 'Unpin...' : 'Pin...',
              onClick: handlePin,
              glyph: isPinned ? PinFilledIcon : PinEmptyIcon,
            }
          : null,
        isActuallyTaggable
          ? {
              label: `${tagsCount > 0 ? 'Edit' : 'Add'} tags...`,
              onClick: handleTags,
              glyph: TagIcon,
            }
          : null,
        isCommentable
          ? {
              label: `${comment != null ? 'Edit' : 'Add'} comment...`,
              onClick: handleComment,
              glyph: CommentIcon,
            }
          : null,
        isStarrable
          ? {
              label: isStarred ? 'Remove from favorites' : 'Add to favorites',
              onClick: handleStar,
              glyph: isStarred ? StarFilledIcon : StarEmptyIcon,
            }
          : null,
        compareDropdownActionItem,
      ].filter(notNull),
    [
      isActuallyPinnable,
      isActuallyTaggable,
      isCommentable,
      isStarrable,
      compareDropdownActionItem,
      comment,
      isPinned,
      isStarred,
      tagsCount,
      handlePin,
      handleTags,
      handleComment,
      handleStar,
    ],
  )
  const skipAssignInvestigation = useSkipAssignInvestigation(buildTypeId, branch, fromBuildList)
  const buildIds = useMemo(() => (buildId != null ? [buildId] : []), [buildId])
  return (
    <>
      <ActionsDropdown
        data={items}
        beforeList={fromBuildList ? beforeList : undefined}
        {...restProps}
        skipAssignInvestigation={skipAssignInvestigation}
      />
      {isCommentable && buildId != null && (
        <CommentDialog buildIds={buildIds} onAction={onAction} />
      )}
      {isActuallyPinnable && buildTypeId != null && buildId != null && (
        <PinDialog buildIds={buildIds} buildTypeId={buildTypeId} onAction={onAction} />
      )}
      {isActuallyPinnable && buildTypeId != null && buildId != null && (
        <EditPinCommentDialog buildIds={buildIds} buildTypeId={buildTypeId} onAction={onAction} />
      )}
      {isActuallyTaggable && buildTypeId != null && (
        <TagDialog buildIds={buildIds} buildTypeId={buildTypeId} onAction={onAction} />
      )}
      <BuildTypeInvestigationHistoryPopup buildTypeId={buildTypeId} id={buildId} />
    </>
  )
}

const mapStateToProps = (state: State, props: ReduxOwnProps): StateProps => {
  const build = getBuild(state, props.buildId)
  const buildTypeId = build?.buildType
  const isQueued = build?.state === 'queued'
  const {projectId} = getBuildType(state, buildTypeId) || {}
  const isCustomizedParams = !!build?.customization?.parameters
  const isCustomizedChanges = !!build?.customization?.changes
  const isCustomizedArtifacts = !!build?.customization?.artifactDependencies
  const isCustomizedDependencies = !!build?.customization?.dependencies
  const branch = !build?.defaultBranch ? parseBranch(build?.branchName) : null
  const isSakuraUI = getIsSakuraUI(state)
  let entityHref = isSakuraUI ? getOldWebBuildLink(build?.id, isQueued) : null

  if (entityHref != null && props.fromBuildList === true) {
    entityHref += `&fromBuildList=true`
  }

  return {
    projectId,
    entityHref,
    isFinishedBuild: build?.state === 'finished',
    icon:
      props.fromBuildList &&
      (isCustomizedParams ||
        isCustomizedChanges ||
        isCustomizedArtifacts ||
        isCustomizedDependencies)
        ? 'filters'
        : undefined,
    buildTypeId,
    comment: build?.comment?.text,
    isPinned: build?.pinned,
    isStarred: getIsStarred(state, props.buildId),
    tagsCount: getTagsCount(state, props.buildId),
    branch,
  }
}

const BuildActionsDropdownContainer: ComponentType<BuildActionsDropdownProps> = compose(
  withBuildId,
  connect(mapStateToProps, actionCreators),
  React.memo,
)(function OverviewActionsOuterContainer(props: Props) {
  return (
    <Suspense>
      <OverviewActionsContainer {...props} />
    </Suspense>
  )
})

export default BuildActionsDropdownContainer
