import {wrapDisplayName} from '@jetbrains/teamcity-ui/dist/utils'
import type {ReactNode} from 'react'
import {Suspense} from 'react'

import type {HOC} from '../types'

export default function withSuspense<P>(getFallback?: (arg0: P) => ReactNode): HOC<P, P> {
  return BaseComponent => {
    function WithSuspense(props: P) {
      return (
        <Suspense fallback={getFallback?.(props)}>
          <BaseComponent {...props} key={undefined} />
        </Suspense>
      )
    }

    if (process.env.NODE_ENV !== 'production') {
      WithSuspense.displayName = wrapDisplayName(BaseComponent, 'withSuspense')
    }

    return WithSuspense
  }
}
