import Checkbox from '@jetbrains/ring-ui-built/components/checkbox/checkbox'
import Text from '@jetbrains/ring-ui-built/components/text/text'
import type * as React from 'react'

import {getHasDependencies} from '../../../../selectors'
import type {BuildId} from '../../../../types'

import styles from './TagsInputFooter.module.css'

import {useAppSelector} from 'src/hooks/react-redux'

type Props = {
  buildIds: readonly BuildId[]
  checked: boolean
  onChange: (event: React.SyntheticEvent<HTMLInputElement>) => unknown
}
export default function TagsInputFooter({buildIds, ...props}: Props) {
  const multiple = buildIds.length > 1
  const hasDependencies = useAppSelector(state =>
    buildIds.some(id => getHasDependencies(state, id)),
  )
  return hasDependencies || multiple ? (
    <div className={styles.container}>
      {hasDependencies && (
        <div className={styles.checkboxWrapper}>
          <Checkbox {...props}>{'Apply to all snapshot dependencies'}</Checkbox>
        </div>
      )}
      <Text info>{`Note: the existing tags ${
        multiple ? '' : 'of the dependencies '
      }will be preserved`}</Text>
    </div>
  ) : null
}
