import {withProps} from 'recompose'

import compose from 'lodash/flowRight'
import type * as React from 'react'
import {connect, type ResolveThunks} from 'react-redux'
import {graphql, useLazyLoadQuery} from 'react-relay'

import type {DialogOwnProps, DialogProps} from '../../../../hocs/withDialogContainer'
import withDialogContainer from '../../../../hocs/withDialogContainer'
import withSuspense from '../../../../hocs/withSuspense'
import type {State} from '../../../../reducers/types'
import {getBuild, makeGetTags} from '../../../../selectors'
import type {BuildId, BuildTypeId, HOC, NormalizedBuild, Tag} from '../../../../types'
import {DialogType} from '../../../../types'
import {emptyArray} from '../../../../utils/empty'
import {notNull} from '../../../../utils/guards'

import type {PinDialogBuildTypeTagsQuery} from './__generated__/PinDialogBuildTypeTagsQuery.graphql'
import PinDialog from './PinDialog'
import {pinBuildFromDialog} from './PinDialog.actions'

type BaseProps = {
  buildIds: readonly BuildId[]
  buildTypeId?: BuildTypeId
  onAction?: () => unknown
}
type OwnProps = DialogOwnProps<BaseProps>
type ReduxOwnProps = DialogProps<BaseProps>
type StateProps = {
  tags: ReadonlyArray<Tag>
  isPinned?: boolean
  pinComment?: string
}
type AddProps = {isEditComment?: boolean}
const actionCreators = {
  pinBuild: pinBuildFromDialog,
}

const mapStateToProps: () => (state: State, props: ReduxOwnProps) => StateProps = () => {
  const getTags = makeGetTags()
  return (state, {buildIds}) => {
    const build: Partial<NormalizedBuild> = getBuild(state, buildIds[0]) || {}
    const tags = buildIds.length > 1 ? emptyArray : getTags(state, buildIds[0])
    const {pinned: isPinned, pinInfo} = build
    return {
      tags,
      isPinned,
      pinComment: buildIds.length > 1 ? '' : pinInfo?.text,
    }
  }
}

type Props = ReduxOwnProps & StateProps & ResolveThunks<typeof actionCreators>
const connector: HOC<Props, ReduxOwnProps> = connect(mapStateToProps, actionCreators)

const buildTypeTagsQuery = graphql`
  query PinDialogBuildTypeTagsQuery($btLocator: String!, $skip: Boolean!) {
    buildTypeBuildTags(btLocator: $btLocator) @skip(if: $skip) {
      tag {
        name
      }
    }
  }
`

function PinDialogContainer({isOpened, ...restProps}: Props & AddProps) {
  const {buildTypeBuildTags} = useLazyLoadQuery<PinDialogBuildTypeTagsQuery>(buildTypeTagsQuery, {
    btLocator: `id:${restProps.buildTypeId}`,
    skip: !isOpened || restProps.buildTypeId == null,
  })
  const buildTypeTags = buildTypeBuildTags?.tag?.map(tag => tag.name).filter(notNull) ?? []
  return isOpened ? <PinDialog {...restProps} buildTypeTags={buildTypeTags} /> : null
}

export default compose(
  withDialogContainer(DialogType.PIN, (_, {buildIds}: OwnProps) => buildIds.join(',')),
  connector,
  withSuspense(),
)(PinDialogContainer)
export const EditPinCommentDialog: React.ComponentType<OwnProps> = compose(
  withDialogContainer(DialogType.EDIT_PIN_COMMENT, (_, {buildIds}: OwnProps) => buildIds.join(',')),
  connector,
  withProps<AddProps, Props>({
    isEditComment: true,
  }),
  withSuspense(),
)(PinDialogContainer)
