import Button from '@jetbrains/ring-ui-built/components/button/button'
import Dialog from '@jetbrains/ring-ui-built/components/dialog/dialog'
import {Size} from '@jetbrains/ring-ui-built/components/input/input'
import {Content, Header} from '@jetbrains/ring-ui-built/components/island/island'
import Panel from '@jetbrains/ring-ui-built/components/panel/panel'
import type {SelectItem} from '@jetbrains/ring-ui-built/components/select/select'
import TagsInput from '@jetbrains/ring-ui-built/components/tags-input/tags-input'
import plur from 'plur'
import * as React from 'react'
import {graphql, useLazyLoadQuery} from 'react-relay'

import type {BuildId, BuildTypeId, RingTag, Tag} from '../../../../types'
import {notNull} from '../../../../utils/guards'
import TagsInputFooter from '../TagsInputFooter/TagsInputFooter'

import type {TagDialogBuildTypeTagsQuery} from './__generated__/TagDialogBuildTypeTagsQuery.graphql'

type Props = {
  tags: ReadonlyArray<Tag>
  buildIds: BuildId[]
  buildTypeId?: BuildTypeId
  isProcessing: boolean
  isOpened: boolean
  dialogHasError?: boolean
  closeDialog: () => unknown
  saveTags: (
    buildIds: BuildId[],
    tags: ReadonlyArray<Tag>,
    buildTypeId?: BuildTypeId,
    applyToChainBuilds?: boolean,
  ) => Promise<unknown>
  onAction?: () => unknown
}

// Converts RingUI select response to TagType
const adaptRingUITagToTagType: (tag: RingTag) => Tag = tag => ({
  name: String(tag.label),
  private: false,
})

// Converts TagType to RingUI InputTags type
const adaptTagTypeToRingUIType = (tag: Tag | string): SelectItem<RingTag> => {
  const key = typeof tag === 'string' ? tag : tag?.name
  return {
    label: key,
    key,
  }
}

const dataSource =
  (buildTypeTags: ReadonlyArray<string>) =>
  ({query}: {query: string}): ReadonlyArray<SelectItem> =>
    buildTypeTags
      .filter(tag => tag.toLowerCase().includes(query.toLowerCase()))
      .map(adaptTagTypeToRingUIType)

const buildTypeTagsQuery = graphql`
  query TagDialogBuildTypeTagsQuery($btLocator: String!, $skip: Boolean!) {
    buildTypeBuildTags(btLocator: $btLocator) @skip(if: $skip) {
      tag {
        name
      }
    }
  }
`

function TagDialog(props: Props) {
  const {buildTypeBuildTags} = useLazyLoadQuery<TagDialogBuildTypeTagsQuery>(buildTypeTagsQuery, {
    btLocator: `id:${props.buildTypeId}`,
    skip: props.buildTypeId == null,
  })
  const buildTypeTags = buildTypeBuildTags?.tag?.map(tag => tag.name).filter(notNull)

  const [tags, setTags] = React.useState(props.tags)
  const [applyToChainBuilds, setApplyToChainBuilds] = React.useState(false)

  const handleAddTag: (arg0: {tag: RingTag}) => void = ({tag}) => {
    setTags(prevTags => [...prevTags, adaptRingUITagToTagType(tag)])
  }

  const handleRemoveTag: (arg0: {tag: RingTag}) => void = ({tag}) => {
    setTags(prevTags =>
      prevTags.filter(stateTag => adaptRingUITagToTagType(tag).name !== stateTag.name),
    )
  }

  const handleSave: () => unknown = async () => {
    await props.saveTags(props.buildIds, tags, props.buildTypeId, applyToChainBuilds)
    props.onAction?.()
  }

  const handleCheckboxClick: (arg0: React.SyntheticEvent<HTMLInputElement>) => void = e => {
    setApplyToChainBuilds(e.currentTarget.checked)
  }

  const tagsInput = (
    <TagsInput
      tags={tags.map(adaptTagTypeToRingUIType)}
      onAddTag={handleAddTag}
      onRemoveTag={handleRemoveTag}
      notFoundMessage=""
      placeholder={'Enter tags'}
      dataSource={buildTypeTags && buildTypeTags.length > 0 ? dataSource(buildTypeTags) : undefined}
      allowAddNewTags
      autoOpen
      size={Size.L}
    />
  )

  const {closeDialog, isProcessing, buildIds} = props
  const buildOrBuilds = plur('Build', buildIds.length)
  const title = tags.length > 0 ? `Edit ${buildOrBuilds} Tags` : `Add ${buildOrBuilds} Tags`
  return (
    <Dialog
      label={title}
      onCloseAttempt={isProcessing ? undefined : closeDialog}
      show
      showCloseButton={!isProcessing}
      closeButtonInside
      trapFocus
      autoFocusFirst={false}
    >
      <Header>{title}</Header>
      <Content>
        {tagsInput}

        <TagsInputFooter
          buildIds={buildIds}
          checked={applyToChainBuilds}
          onChange={handleCheckboxClick}
        />
      </Content>
      <Panel>
        <Button onClick={handleSave} loader={isProcessing} primary>
          {'Save'}
        </Button>
        <Button disabled={isProcessing} onClick={closeDialog}>
          {'Cancel'}
        </Button>
      </Panel>
    </Dialog>
  )
}

export default TagDialog
