import Button from '@jetbrains/ring-ui-built/components/button/button'
import Dialog from '@jetbrains/ring-ui-built/components/dialog/dialog'
import Input, {Size} from '@jetbrains/ring-ui-built/components/input/input'
import {Content, Header} from '@jetbrains/ring-ui-built/components/island/island'
import Panel from '@jetbrains/ring-ui-built/components/panel/panel'
import type {SelectItem} from '@jetbrains/ring-ui-built/components/select/select'
import TagsInput from '@jetbrains/ring-ui-built/components/tags-input/tags-input'
import plur from 'plur'
import * as React from 'react'

import type {Tag, BuildId, BuildTypeId, RingTag} from '../../../../types'
import {noop} from '../../../../utils/empty'
import TagsInputFooter from '../TagsInputFooter/TagsInputFooter'

import type {PinBuildArg} from './PinDialog.actions'

import styles from './PinDialog.module.css'

type DefaultProps = {
  buildTypeTags: readonly string[]
  closeDialog: () => unknown
  isProcessing: boolean
  isEditComment: boolean
}
type Props = DefaultProps & {
  tags: ReadonlyArray<Tag>
  buildIds: readonly BuildId[]
  buildTypeId?: BuildTypeId
  isPinned?: boolean
  pinComment?: string
  dialogHasError?: boolean
  pinBuild: (arg: PinBuildArg) => Promise<unknown>
  onAction?: () => unknown
}
type State = {
  tags: ReadonlyArray<Tag>
  pinComment?: string
  applyToChainBuilds: boolean
}
class PinDialog extends React.PureComponent<Props, State> {
  static defaultProps: DefaultProps = {
    buildTypeTags: [],
    isProcessing: false,
    closeDialog: noop,
    isEditComment: false,
  }

  state: State = {
    tags: this.props.tags,
    pinComment: this.props.pinComment,
    applyToChainBuilds: false,
  }

  dataSource: (arg0: {query: string}) => Array<SelectItem> = ({query}) =>
    this.props.buildTypeTags
      .filter(tag => tag.toLowerCase().includes(query.toLowerCase()))
      .map<any>(tag => this.adaptTagTypeToRingUIType(tag))

  // Converts RingUI select response to TagType
  adaptRingUITagToTagType: (tag: RingTag) => Tag = tag => ({
    name: String(tag.label),
    private: false,
  })

  // Converts TagType to RingUI InputTags type
  adaptTagTypeToRingUIType: (arg0: Tag | string) => RingTag = tag => {
    const key = typeof tag === 'string' ? tag : tag?.name
    return {
      label: key,
      key,
    }
  }

  handleAddTag: (arg0: {tag: RingTag}) => void = ({tag}) => {
    this.setState(prevState => ({
      tags: [...prevState.tags, this.adaptRingUITagToTagType(tag)],
    }))
  }

  handleRemoveTag: (arg0: {tag: RingTag}) => void = ({tag}) => {
    this.setState(prevState => ({
      tags: [
        ...prevState.tags.filter(
          stateTag => this.adaptRingUITagToTagType(tag).name !== stateTag.name,
        ),
      ],
    }))
  }

  handleCommentClear: () => void = () => {
    this.setState({
      pinComment: '',
    })
  }

  handleSave: () => void = async () => {
    const {isPinned, isEditComment, buildIds, buildTypeId, pinBuild, onAction} = this.props
    const {applyToChainBuilds, pinComment, tags} = this.state
    await pinBuild({
      ids: buildIds,
      buildTypeId,
      parameters: {
        pinComment,
        pin: !isPinned || isEditComment,
        tags,
        applyToChainBuilds,
      },
    })
    onAction?.()
  }

  handleCommentChange = (event: React.ChangeEvent<HTMLTextAreaElement>) => {
    this.setState({
      pinComment: event.currentTarget.value,
    })
  }

  handleCheckboxClick = (e: React.SyntheticEvent<HTMLInputElement>) => {
    this.setState({
      applyToChainBuilds: e.currentTarget.checked,
    })
  }

  render(): React.ReactNode {
    const {closeDialog, isProcessing, isPinned, buildTypeTags, isEditComment, buildIds} = this.props
    const buildOrBuilds = plur('Build', buildIds.length)
    const title = isEditComment
      ? 'Update pin info'
      : isPinned
        ? `Unpin ${buildOrBuilds}`
        : `Pin ${buildOrBuilds}`
    return (
      <Dialog
        label={title}
        onCloseAttempt={isProcessing ? undefined : closeDialog}
        show
        showCloseButton={!isProcessing}
        closeButtonInside
        autoFocusFirst
        trapFocus
      >
        <Header>{title}</Header>
        <Content>
          <Input
            className={styles.message}
            multiline
            value={this.state.pinComment}
            disabled={isProcessing}
            onChange={this.handleCommentChange}
            onClear={this.handleCommentClear}
            label={'Pin message'}
            size={Size.L}
            placeholder={'Type here'}
          />

          <TagsInput
            tags={this.state.tags.map(tag => this.adaptTagTypeToRingUIType(tag))}
            onAddTag={this.handleAddTag}
            onRemoveTag={this.handleRemoveTag}
            placeholder={'Enter tags'}
            notFoundMessage=""
            dataSource={buildTypeTags.length > 0 ? this.dataSource : undefined}
            allowAddNewTags
            size={Size.L}
          />

          <TagsInputFooter
            buildIds={buildIds}
            checked={this.state.applyToChainBuilds}
            onChange={this.handleCheckboxClick}
          />
        </Content>
        <Panel>
          <Button onClick={this.handleSave} loader={isProcessing} primary>
            {isEditComment ? 'Submit' : isPinned ? 'Unpin' : 'Pin'}
          </Button>
          <Button disabled={isProcessing} onClick={closeDialog}>
            {'Cancel'}
          </Button>
        </Panel>
      </Dialog>
    )
  }
}

export default PinDialog
