import Button from '@jetbrains/ring-ui-built/components/button/button'
import Dialog from '@jetbrains/ring-ui-built/components/dialog/dialog'
import Input, {Size} from '@jetbrains/ring-ui-built/components/input/input'
import {Content, Header} from '@jetbrains/ring-ui-built/components/island/island'
import Panel from '@jetbrains/ring-ui-built/components/panel/panel'
import plur from 'plur'
import * as React from 'react'

import type {BuildId} from '../../../../types'
import {noop} from '../../../../utils/empty'

import type {SaveCommentArg} from './CommentDialog.actions'

type DefaultProps = {
  closeDialog: () => unknown
}
type Props = DefaultProps & {
  comment: string
  saveComment: (arg: SaveCommentArg) => Promise<unknown>
  buildIds: readonly BuildId[]
  isOpened: boolean
  isProcessing: boolean
  dialogHasError?: boolean
  onAction?: () => unknown
}
type State = {
  comment: string
}

class CommentDialog extends React.PureComponent<Props, State> {
  static defaultProps: DefaultProps = {
    closeDialog: noop,
  }

  state: State = {
    comment: this.props.comment,
  }

  handleChange: (event: React.ChangeEvent<HTMLTextAreaElement>) => void = event => {
    this.setState({
      comment: event.currentTarget.value,
    })
  }

  handleClear: () => void = () => {
    this.setState({
      comment: '',
    })
  }

  handleSave: () => unknown = async () => {
    await this.props.saveComment({buildIds: this.props.buildIds, text: this.state.comment})
    this.props.onAction?.()
  }

  render(): React.ReactNode {
    const {comment, isProcessing, closeDialog, isOpened, dialogHasError, buildIds} = this.props
    const buildOrBuilds = plur('Build', buildIds.length)
    const title = comment ? `Edit ${buildOrBuilds} Comment` : `Add ${buildOrBuilds} Comment`
    return isOpened ? (
      <Dialog
        label={title}
        onCloseAttempt={isProcessing ? undefined : closeDialog}
        showCloseButton={!isProcessing}
        closeButtonInside
        autoFocusFirst
        show
        trapFocus
      >
        <Header>{title}</Header>
        <Content>
          <Input
            multiline
            value={this.state.comment}
            disabled={isProcessing}
            onChange={this.handleChange}
            onClear={this.handleClear}
            error={dialogHasError === true ? 'Something went wrong' : null}
            label={'Comment'}
            size={Size.L}
            placeholder={'Type here'}
          />
        </Content>
        <Panel>
          <Button
            loader={isProcessing}
            disabled={comment === this.state.comment}
            onClick={this.handleSave}
            primary
          >
            {'Save'}
          </Button>
          <Button disabled={isProcessing} onClick={closeDialog}>
            {'Cancel'}
          </Button>
        </Panel>
      </Dialog>
    ) : null
  }
}

export default CommentDialog
